{"filePath":"/testbed/src/payhook/receiver.py","content":""""Provider notification adapter for the billing service.

Accepts the deliveries described in ``docs/provider-notifications.md``:

* ``X-Pay-Signature: v1=<hex>`` -- HMAC-SHA256 over the ASCII timestamp, one
  ``.`` byte and the exact received body bytes.
* ``X-Pay-Receipt: r0=<hex>`` -- the legacy credential used for deliveries whose
  body the edge relay reformats, so the v1 body digest cannot match.

Security note on the r0 credential. The deployed v0 receipt is
``HMAC(secret, timestamp + "." + event_id)``: it proves that some delivery with
that ``event_id`` was issued inside the 300 second window and nothing else.
``account_id``, ``amount_minor`` and ``currency`` are not covered, and this
function's return value is what the crediting worker consumes. Verifying only
the ``event_id`` would therefore let anyone holding one legitimate receipt --
their own zero-value test payment, or any delivery they can observe -- resend
it with a body of their choosing and have an arbitrary amount credited to an
arbitrary account, because no digest binds the received body and nothing here
deduplicates events. That is a funds-diversion hole, so the r0 credential is
verified over the canonical encoding of every field returned below, i.e. the
same construction as v1 with a canonical body instead of the wire body. The
relay change needed is confined to the digest input (see ``_receipt_message``).
Until the relay signs that canonical payload, legacy deliveries failing closed
is the intended behaviour: rejecting them is an availability problem, accepting
them unauthenticated is a correctness problem for somebody else's money.

Both paths share one timestamp window check and both compare digests with
``hmac.compare_digest``.
"""

import hashlib
import hmac
import json
import re
from decimal import Decimal
from decimal import InvalidOperation

from payhook.errors import InvalidNotification

_WINDOW_SECONDS = Decimal(300)
_TIMESTAMP_RE = re.compile(r"\A[+-]?[0-9]+(?:\.[0-9]+)?\Z")
_HEX_RE = re.compile(r"\A[0-9a-fA-F]+\Z")
_CURRENCY_RE = re.compile(r"\A[A-Z]{3}\Z")
_TIMESTAMP_HEADER = "x-pay-timestamp"
_SIGNATURE_HEADER = "x-pay-signature"
_RECEIPT_HEADER = "x-pay-receipt"
_CREDITED_FIELDS = ("event_id", "account_id", "amount_minor", "currency")


def _text(value):
    """Best-effort textual form of a header name or value."""
    if isinstance(value, str):
        return value
    if isinstance(value, (bytes, bytearray, memoryview)):
        return bytes(value).decode("latin-1")
    if isinstance(value, int) and not isinstance(value, bool):
        return str(value)
    return None


def _header_name(name):
    normalized = _text(name)
    if normalized is None:
        return None
    normalized = normalized.strip().lower()
    if normalized.startswith("http_"):
        normalized = normalized[5:]
    return normalized.replace("_", "-")


def _header_values(headers, name):
    """All values carried for `name`, matched case- and separator-insensitively.

    Repeated headers are folded into one comma-separated value, which is how
    the ingress presents them anyway.
    """
    items = getattr(headers, "items", None)
    if items is None:
        return []
    try:
        pairs = list(items())
    except TypeError:
        return []
    return [value for key, value in pairs if _header_name(key) == name
            for value in _split_header(_text(value)) if value is not None]


def _split_header(value):
    if value is None:
        return []
    return [part for part in (chunk.strip() for chunk in value.split(",")) if part]


def _secret_bytes(secret):
    if isinstance(secret, str):
        secret = secret.encode("utf-8")
    if isinstance(secret, (bytes, bytearray, memoryview)) and len(bytes(secret)):
        return bytes(secret)
    raise InvalidNotification("notification secret is not configured")


def _as_bytes(raw_body):
    if isinstance(raw_body, str):
        return raw_body.encode("utf-8")
    if isinstance(raw_body, (bytes, bytearray, memoryview)):
        return bytes(raw_body)
    raise InvalidNotification("notification body must be bytes or text")


def _check_window(timestamp_text, now):
    """Return the received timestamp within the delivery window."""
    for candidate in (timestamp_text, _text(now)):
        if candidate is None or not _TIMESTAMP_RE.match(candidate):
            raise InvalidNotification("missing or malformed X-Pay-Timestamp")
        try:
            value = Decimal(candidate)
        except InvalidOperation:
            raise InvalidNotification("missing or malformed timestamp") from None
        if candidate is timestamp_text:
            received = value
        else:
            reference = value
    if abs(received - reference) > _WINDOW_SECONDS:
        raise InvalidNotification("timestamp outside the delivery window")
    return timestamp_text.encode("ascii")


def _parse_json(body):
    try:
        text = body.decode("utf-8")
    except UnicodeDecodeError:
        raise InvalidNotification("notification body is not valid UTF-8") from None
    try:
        payload = json.loads(text, parse_constant=_reject_constant)
    except InvalidNotification:
        raise
    except ValueError:
        raise InvalidNotification("notification body is not valid JSON") from None
    if not isinstance(payload, dict):
        raise InvalidNotification("notification body must be a JSON object")
    return payload


def _reject_constant(name):
    raise InvalidNotification("NaN and Infinity are not accepted in JSON bodies")


def _credited_fields(payload):
    fields = {}
    for name in ("event_id", "account_id"):
        value = payload.get(name)
        if not isinstance(value, str) or not value:
            raise InvalidNotification("missing or malformed %s" % name)
        fields[name] = value
    amount = payload.get("amount_minor")
    if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
        raise InvalidNotification("amount_minor must be a nonnegative integer")
    fields["amount_minor"] = amount
    currency = payload.get("currency")
    if not isinstance(currency, str) or not _CURRENCY_RE.match(currency):
        raise InvalidNotification("currency must be three uppercase ASCII letters")
    fields["currency"] = currency
    return fields


def _digests(header_values, scheme):
    """Lowercase hex digests from `<scheme>=<hex>` entries of these headers."""
    for value in header_values:
        tag, separator, digest = value.partition("=")
        if not separator or tag.strip().lower() != scheme:
            continue
        digest = digest.strip()
        if _HEX_RE.match(digest) and len(digest) % 8 == 0:
            yield digest.lower()


def _any_digest_matches(secret, timestamp, message, digests):
    expected = hmac.new(secret, timestamp + b"." + message,
                        hashlib.sha256).hexdigest()
    for digest in digests:
        if hmac.compare_digest(expected, digest):
            return True
    return False


def _receipt_message(fields):
    """Canonical body the legacy r0 receipt must cover.

    The relay reformats the wire body, so the receipt cannot be taken over the
    bytes that arrive. It is instead taken over a canonical encoding of the
    fields that are actually credited: this function's whole return value. The
    relay must compute the same encoding over the same four fields
    (compact separators, sorted keys, non-ASCII preserved, UTF-8).
    """
    return json.dumps({name: fields[name] for name in _CREDITED_FIELDS},
                      sort_keys=True, separators=(",", ":"),
                      ensure_ascii=False).encode("utf-8")


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    key = _secret_bytes(secret)
    body = _as_bytes(raw_body)
    timestamps = _header_values(headers, _TIMESTAMP_HEADER)
    if len(timestamps) != 1:
        raise InvalidNotification("exactly one X-Pay-Timestamp header is required")
    timestamp = _check_window(timestamps[0], now)

    signature = _header_values(headers, _SIGNATURE_HEADER)
    if _any_digest_matches(key, timestamp, body, _digests(signature, "v1")):
        return dict(_credited_fields(_parse_json(body)))

    fields = _credited_fields(_parse_json(body))
    receipt = _header_values(headers, _RECEIPT_HEADER)
    if _any_digest_matches(key, timestamp, _receipt_message(fields),
                           _digests(receipt, "r0")):
        return dict(fields)

    raise InvalidNotification("notification carries no digest matching this body")


if __name__ == "__main__":
    raise SystemExit("this module is imported by the billing service")
"}

